foreach (var category in Categories)
{
    var bar = K.Bar(category.Candidate, 100, ArcProgressSize.Sm);
    bar.Baseline = category.Baseline;      // 基线刻度，落在条上
    var delta = category.Candidate - category.Baseline;

    grid.Children.Add(K.Stack(3,
        K.Row(6,
            K.Text(category.Name, "arc-label"),
            K.Caption($"{category.Candidate:0.0}% · {(delta >= 0 ? "+" : "")}{delta:0.0}")),
        bar));
}
